import{_ as e,o as a,c as s,ao as d}from"./chunks/framework.D_e_NHVr.js";const p=JSON.parse('{"title":"Losses","description":"","frontmatter":{},"headers":[],"relativePath":"losses.md","filePath":"losses.md","lastUpdated":null}'),o={name:"losses.md"};function i(l,t,r,n,c,h){return a(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="Losses" tabindex="-1">Losses <a class="header-anchor" href="#Losses" aria-label="Permalink to &quot;Losses {#Losses}&quot;">​</a></h1><p>Losses are concrete callable types, following the <a href="https://lux.csail.mit.edu/stable/api/Lux/utilities#Loss-Functions" target="_blank" rel="noreferrer">Lux loss API</a>: they take <code>(model, ps, st, data)</code> and return <code>(scalar_loss, updated_state, NamedTuple())</code>.</p><h2 id="Prediction-Shape" tabindex="-1">Prediction Shape <a class="header-anchor" href="#Prediction-Shape" aria-label="Permalink to &quot;Prediction Shape {#Prediction-Shape}&quot;">​</a></h2><p>All losses expect 3D predictions: <code>(outsize, K, batch)</code> where <code>K</code> is the ensemble size. Other shapes are rejected.</p><p><code>reduce_pred</code> averages over <code>K</code> on raw predictions before any transformation.</p><h2 id="Usage" tabindex="-1">Usage <a class="header-anchor" href="#Usage" aria-label="Permalink to &quot;Usage {#Usage}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># callable loss functor</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LossType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:mse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># same, from a symbol (`MSE()`)</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MSE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()(model, ps, st, data)</span></span></code></pre></div><p><code>NeuroTabRegressor</code> / <code>NeuroTabClassifier</code> still take <code>loss=:mse</code> (a symbol). <code>fit</code> converts that once to a functor and stores it on <code>NeuroTabModel.loss</code>.</p><h2 id="Supported-Losses" tabindex="-1">Supported Losses <a class="header-anchor" href="#Supported-Losses" aria-label="Permalink to &quot;Supported Losses {#Supported-Losses}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Symbol</th><th style="text-align:right;">Type</th><th style="text-align:right;">Pred shape</th><th style="text-align:right;">Target</th><th style="text-align:right;">Notes</th></tr></thead><tbody><tr><td style="text-align:right;"><code>:mse</code></td><td style="text-align:right;"><code>MSE</code></td><td style="text-align:right;"><code>(1, K, B)</code></td><td style="text-align:right;">scalar</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>:mae</code></td><td style="text-align:right;"><code>MAE</code></td><td style="text-align:right;"><code>(1, K, B)</code></td><td style="text-align:right;">scalar</td><td style="text-align:right;"></td></tr><tr><td style="text-align:right;"><code>:huber</code></td><td style="text-align:right;"><code>Huber</code></td><td style="text-align:right;"><code>(1, K, B)</code></td><td style="text-align:right;">scalar</td><td style="text-align:right;">δ = 1; quadratic within δ, linear beyond</td></tr><tr><td style="text-align:right;"><code>:logloss</code></td><td style="text-align:right;"><code>LogLoss</code></td><td style="text-align:right;"><code>(1, K, B)</code></td><td style="text-align:right;"><code>{0, 1}</code></td><td style="text-align:right;">raw logits</td></tr><tr><td style="text-align:right;"><code>:mlogloss</code></td><td style="text-align:right;"><code>MLogLoss</code></td><td style="text-align:right;"><code>(C, K, B)</code></td><td style="text-align:right;"><code>{1, …, C}</code></td><td style="text-align:right;">raw logits</td></tr><tr><td style="text-align:right;"><code>:gaussian_mle</code></td><td style="text-align:right;"><code>GaussianMLE</code></td><td style="text-align:right;"><code>(2, K, B)</code></td><td style="text-align:right;">scalar</td><td style="text-align:right;"><code>pred[1,:,:]</code> = μ, <code>pred[2,:,:]</code> = log-σ</td></tr><tr><td style="text-align:right;"><code>:tweedie</code></td><td style="text-align:right;"><code>Tweedie</code></td><td style="text-align:right;"><code>(1, K, B)</code></td><td style="text-align:right;">non-negative</td><td style="text-align:right;">log-scale pred, ρ = 1.5</td></tr><tr><td style="text-align:right;"><code>:poisson</code></td><td style="text-align:right;"><code>Poisson</code></td><td style="text-align:right;"><code>(1, K, B)</code></td><td style="text-align:right;">non-negative</td><td style="text-align:right;">log-scale pred, Poisson deviance</td></tr><tr><td style="text-align:right;"><code>:pearson</code></td><td style="text-align:right;"><code>Pearson</code></td><td style="text-align:right;"><code>(1, K, B)</code></td><td style="text-align:right;">scalar</td><td style="text-align:right;">negative Pearson correlation</td></tr></tbody></table><p>Huber&#39;s threshold is on the training scale: with the default <code>scale_target=true</code>, δ = 1 corresponds to one target standard deviation.</p><h2 id="Multiple-Targets" tabindex="-1">Multiple Targets <a class="header-anchor" href="#Multiple-Targets" aria-label="Permalink to &quot;Multiple Targets {#Multiple-Targets}&quot;">​</a></h2><p>With <code>T</code> targets (a vector <code>target_name</code>), the prediction is <code>(T·outsize, K, B)</code> and the target <code>(T, B)</code>. <code>:gaussian_mle</code> rows interleave per target (μ₁, log-σ₁, μ₂, log-σ₂, …), <code>:pearson</code> takes the mean correlation over targets, and <code>:mlogloss</code> does not support several targets.</p><h2 id="Eval-metrics" tabindex="-1">Eval metrics <a class="header-anchor" href="#Eval-metrics" aria-label="Permalink to &quot;Eval metrics {#Eval-metrics}&quot;">​</a></h2><p><code>metric</code> defaults to the training loss and must be one of the supported losses. <code>:pearson</code> reads the μ rows when the loss is <code>:gaussian_mle</code>.</p><p>The reported value is one score for the full evaluation set. Each batch contributes a sum, divided by the total weight, so unequal batch sizes do not change it. Pad rows have weight 0 and do not count.</p><p><code>:pearson</code> is the exception. Correlation is not a sum of per-row scores, so the reported value is the size-weighted mean of the per-batch or per-group correlations, not one correlation on the concatenated evaluation set. Pads are still dropped inside each batch.</p><h2 id="Data-Tuples" tabindex="-1">Data Tuples <a class="header-anchor" href="#Data-Tuples" aria-label="Permalink to &quot;Data Tuples {#Data-Tuples}&quot;">​</a></h2><p>The loss sees a 2-, 3-, or 4-tuple. <code>x</code> is the model input. A grouped loader wraps it as <code>(features, mask)</code> and always includes <code>w</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Tuple</th><th style="text-align:right;">When</th></tr></thead><tbody><tr><td style="text-align:right;"><code>(x, y)</code></td><td style="text-align:right;">ungrouped, no <code>weight_name</code>, no <code>offset_name</code></td></tr><tr><td style="text-align:right;"><code>(x, y, w)</code></td><td style="text-align:right;"><code>weight_name</code>, or any grouped batch</td></tr><tr><td style="text-align:right;"><code>(x, y, w, offset)</code></td><td style="text-align:right;"><code>offset_name</code>. Ungrouped batches with no <code>weight_name</code> use <code>w = 1</code></td></tr></tbody></table><p>See <a href="/NeuroTabModels.jl/previews/PR85/models/padding-mask#Grouped-padding-and-masks">Grouped padding and masks</a> for <code>w</code> and <code>mask</code> on a grouped batch.</p><h2 id="Signature" tabindex="-1">Signature <a class="header-anchor" href="#Signature" aria-label="Permalink to &quot;Signature {#Signature}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">loss</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model, ps, st, data) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">→</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (scalar_loss, updated_state, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NamedTuple</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div>',23)])])}const u=e(o,[["render",i]]);export{p as __pageData,u as default};
